urls = [u.strip() for u in raw_urls_text.strip().splitlines() if u.strip().startswith('http')]
print(f"Total input URLs: {len(urls)}")

# Filter to image URLs (exclude png icons/webp static assets)
image_urls = [u for u in urls if not u.endswith('.png') and not u.endswith('.webp')]

# Unique deduplicated image URLs
unique_image_urls = list(dict.fromkeys(image_urls))
print(f"Unique high-res image URLs: {len(unique_image_urls)}")

dest_dir = r'c:\Users\Admin\Downloads\mini\public\assets\jimmy'
os.makedirs(dest_dir, exist_ok=True)

ctx = ssl.create_default_context()
ctx.check_hostname = False
ctx.verify_mode = ssl.CERT_NONE

saved_files = []
for idx, url in enumerate(unique_image_urls, 1):
    out_file = os.path.join(dest_dir, f'jimmy_{idx}.jpg')
    try:
        req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
        with urllib.request.urlopen(req, context=ctx, timeout=10) as resp:
            data = resp.read()
            if len(data) > 10000: # Only keep valid non-empty images
                with open(out_file, 'wb') as f:
                    f.write(data)
                saved_files.append(f'jimmy_{idx}.jpg')
                print(f'Successfully downloaded photo {idx}/{len(unique_image_urls)} ({len(data)} bytes)')
    except Exception as e:
        print(f'Failed photo {idx}: {e}')

print(f'\nTotal downloaded unique Jimmy photos: {len(saved_files)}')
